import java.util.Scanner;

public class Main {
    static class DisjointSetUnion {
        int[] parent;
        int[] size;

        void initialize(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] == x) return x;
            return parent[x] = find(parent[x]);
        }

        void unite(int a, int b) {
            a = find(a);
            b = find(b);
            if (a != b) {
                if (size[a] < size[b]) {
                    int temp = a;
                    a = b;
                    b = temp;
                }
                parent[b] = a;
                size[a] += size[b];
            }
        }
    }

    static long modPow(long base, int exp, long modulus) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        final long MOD = 1000000007L;

        if (k == 0) {
            System.out.println(modPow(n, n - 1, MOD));
            return;
        }

        DisjointSetUnion dsu = new DisjointSetUnion();
        dsu.initialize(n);
        for (int i = 0; i < n; i++) {
            int target = (int)((long)i * k % n);
            dsu.unite(i, target);
        }

        long answer = 1;
        for (int i = 0; i < n; i++) {
            if (dsu.find(i) != i) continue;
            long t = modPow(k, dsu.size[dsu.find(i)], n);
            if (t == 1) {
                answer = (answer * n) % MOD;
            }
        }
        System.out.println(answer);
        sc.close();
    }
}
